static int vhd_dump_headers(const char *name, int hex) { vhd_context_t vhd; libvhd_set_log_level(1); memset(&vhd, 0, sizeof(vhd)); printf("
%s appears invalid; dumping headers

", name); vhd.fd = open(name, O_DIRECT | O_LARGEFILE | O_RDONLY); if (vhd.fd == -1) return -errno; vhd.file = strdup(name); vhd_read_footer(&vhd, &vhd.footer); vhd_read_header(&vhd, &vhd.header); vhd_print_footer(&vhd.footer, hex); vhd_print_header(&vhd, &vhd.header, hex); close(vhd.fd); free(vhd.file); return 0; }

